'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const fixtures = [
  ['', []],
  ['\uFEFF', []],
  ['\n\n', [[''], ['']]],
  ['\r\n\r\n', [[''], ['']]],
  ['a\rb\r\nc\n', [['a'], ['b'], ['c']]],
  [',,', [['', '', '']]],
  ['""', [['']]],
  ['""""', [['"']]],
  ['"a,b","say ""hi"""\r\nlast,', [['a,b', 'say "hi"'], ['last', '']]],
  ['"a\r\nb\rc\nd",z\r\n', [['a\r\nb\rc\nd', 'z']]],
  ['ab"cd,ef"', [['ab"cd', 'ef"']]],
  ['\uFEFFx,\uFEFFy\n\uFEFFz', [['x', '\uFEFFy'], ['\uFEFFz']]],
  ['😀,"😀"\n', [['😀', '😀']]],
  ['a;"b;c";\r\n', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\t', [['a', 'b', '']], { delimiter: '\t' }],
  ['a\uD83Db', [['a', 'b']], { delimiter: '\uD83D' }],
];

test('grammar survives every pair of chunk boundaries and empty chunks', () => {
  for (const [text, expected, options] of fixtures) {
    assert.deepEqual(parse(text, options), expected);
    for (let first = 0; first <= text.length; first++) {
      for (let second = first; second <= text.length; second++) {
        const parser = createParser(options);
        const records = [];
        for (const chunk of [text.slice(0, first), text.slice(first, second), text.slice(second)]) {
          assert.deepEqual(parser.push(''), []);
          records.push(...parser.push(chunk));
        }
        records.push(...parser.end());
        assert.deepEqual(records, expected, JSON.stringify({ text, first, second }));
        assert.deepEqual(parser.end(), []);
      }
    }
    const parser = createParser(options);
    const records = [];
    for (let index = 0; index < text.length; index++) records.push(...parser.push(text[index]));
    records.push(...parser.end());
    assert.deepEqual(records, expected);
  }
});

test('records emit at CR or LF without waiting; parsers stay independent', () => {
  const a = createParser({ header: true });
  const b = createParser();
  assert.deepEqual(a.push('x,y\r'), [['x', 'y']]);
  assert.deepEqual(b.push('"other'), []);
  assert.deepEqual(a.push(''), []);
  assert.deepEqual(a.push('\n\nunfinished,'), [['']]);
  assert.deepEqual(b.push('"\n'), [['other']]);
  assert.deepEqual(a.end(), [['unfinished', '']]);
  assert.deepEqual(b.end(), []);
  assert.deepEqual(a.end(), []);
  assert.throws(() => a.push(''), Error);
  assert.throws(() => a.push('more'), Error);
});

test('invalid delimiters and chunks fail without coercion', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, false, {}, []]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  for (const chunk of [undefined, null, 1, false, [], {}, Buffer.from('a'), new String('a')]) {
    assert.throws(() => parser.push(chunk), TypeError);
  }
  assert.deepEqual(parser.push('\uFEFFx\n'), [['x']]);
  assert.deepEqual(parser.end(), []);
});

test('syntax failures report physical lines across chunk boundaries', () => {
  const cases = [
    ['"x" ', 1, false],
    ['"x"z', 1, false],
    ['a\r\n"x"z', 2, false],
    ['"a\r\nb\rc\nd" ', 4, false],
    ['"', 1, true],
    ['"a\r\n', 2, true],
    ['a\n"b\rc\n', 4, true],
  ];
  for (const [text, line, atEnd] of cases) {
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser();
      const feed = () => {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
      };
      const check = error => error instanceof SyntaxError && new RegExp(`line ${line}\\b`).test(error.message);
      if (atEnd) {
        feed();
        assert.throws(() => parser.end(), check);
      } else {
        assert.throws(feed, check);
      }
    }
  }
});

test('header conversion preserves duplicates, padding, special keys, and frozen inputs', () => {
  const options = Object.freeze({ header: true });
  const objects = parse('x,x,x_2,x,__proto__,constructor,toString,\na,b,c,d,e,f,g\nz', options);
  assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '']);
  assert.deepEqual(Object.values(objects[0]), ['a', 'b', 'c', 'd', 'e', 'f', 'g', '']);
  assert.deepEqual(Object.values(objects[1]), ['z', '', '', '', '', '', '', '']);
  for (const object of objects) {
    assert.equal(Object.getPrototypeOf(object), Object.prototype);
    for (const key of Object.keys(object)) {
      const descriptor = Object.getOwnPropertyDescriptor(object, key);
      assert.equal(descriptor.enumerable, true);
      assert.equal(descriptor.writable, true);
      assert.equal(descriptor.configurable, true);
    }
  }
  assert.deepEqual(parse('', options), []);
  assert.deepEqual(parse('only,header', options), []);
  assert.deepEqual(parse('a,b', { header: [] }), [['a', 'b']]);
  const header = Object.freeze(['__proto__', '__proto__']);
  const records = Object.freeze([Object.freeze(['a']), Object.freeze(['b', 'c', 'ignored'])]);
  const helperOptions = Object.freeze({ header });
  const converted = toObjects(records, helperOptions);
  assert.deepEqual(Object.values(converted[0]), ['a', '']);
  assert.deepEqual(Object.values(converted[1]), ['b', 'c']);
  assert.deepEqual(header, ['__proto__', '__proto__']);
  assert.deepEqual(records, [['a'], ['b', 'c', 'ignored']]);
});

